dir$s322.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			<!-- $.showToast(p.msg('noDate')); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
			Break;
			}	  		  
    default:
      break;
  }
  return true;
}
dir$s322.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
  	case '10':
       p.showFilter("s322C1", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_ma_noi_di: p.valForm('ma_noi_di'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den')});	  
	  //p.setInactive([ 'ma_noi_di','ma_noi_den'], false);
	  return false;
      break;
    default:
      break;
  }
  return true;
}

dir$s322.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s322HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$s322HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$s322HiddenColumnByDay(p);
      break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$s322.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$s322DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$s322DisabledMasterField(p, g){
    if (p.options.action !="NEW") p.setDisabled(['ma_kh', 'so_ct','ngay_ct', 'ma_nt','ty_gia'], true)
}
function dir$s322HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
}
