-- Áp dụng cho dữ liệu lớn
exec ISWIFTStoredDeleteDataWithKey 'v322', @strIds, '', @dVoucherDate
exec ISWIFTStoredDeleteDataWithKey 'v3220', @strIds, '', @dVoucherDate
