select @dOldVoucherDate = ngay_ct from s322 where id = @id







update @@table set datetime2 = getdate(), user_id2 = @@userId, i_so_ct = @i_so_ct, so_ct = @so_ct where [%whereFieldKey]
update dmttin set status = 0 from dmttin where id0 = rtrim(@id) and xgroup = '@@voucherCode'
if @xfile <> '' update dmttin set status = 1, id0 = @id from dmttin where charindex(id, @xfile) > 0 and xgroup = '@@voucherCode'







select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @ma_ct = '@@voucherCode'
exec ISWIFTStoredGetIdentityNumber '@@voucherCode', '@@table', @id output







if @xfile <> '' update dmttin set status = 1, id0 = @id from dmttin where charindex(id, @xfile) > 0 and xgroup = '@@voucherCode'







select @strIds = rtrim(@id)
if @action = 'NEW' set @dOldVoucherDate = @ngay_ct
update @v322 set id = @id, ma_kh = @ma_kh, ngay_ct = @ngay_ct, so_ct = @so_ct, status = @status, ma_nt = @ma_nt
update @v322 set ngay_hl = @ngay_hl, ngay_hld = @ngay_hld, unit_id = @unit_id
delete v322 where id = @id
delete @v322 where so_luong = 0 or ( gia_nt2 =0 and ban_nt = 0)
insert v322 select * from @v322




update @v3220 set id = @id, ma_kh = @ma_kh, ngay_ct = @ngay_ct, so_ct = @so_ct, status = @status, ma_nt = @ma_nt
update @v3220 set ngay_hl = @ngay_hl, ngay_hld = @ngay_hld, unit_id = @unit_id
delete v3220 where id = @id
insert v3220 select * from @v3220


declare @t_sl numeric(19,4)
select @t_sl=isnull(sum(so_luong),0) from @v322 
update s322 set t_so_luong =@t_sl where id = @id



